entries[3496] = { ["name"] = "Mondstahlbreitschwert", ["text"] = "Wirken in 45 sek.\nTools: Schmiedehammer\nReagenzien:\nStahlbarren (8), Starker Fluxus (2), Schwerer Schleifstein (2), Geringer Mondstein (3), Schweres Leder (3)\nMondstahlbreitschwert\nWird beim Anlegen gebunden\nZweihändig Schwert\n55 - 83 Schaden Tempo 2.80\n(24.64 Schaden pro Sekunde)\n+4 Ausdauer\n+12 Willenskraft\nHaltbarkeit 85 / 85\n31" }
