entries[3949] = { ["name"] = "Versilberte Schrotflinte", ["text"] = "Wirken in 25 sek.\nReagenzien:\nBronzeröhre (2), Surrendes bronzenes Dingsda (2), Schwerer Griff , Silberbarren (3)\nVersilberte Schrotflinte\nWird beim Anlegen gebunden\nDistanz Schusswaffe\n19 - 37 Schaden Tempo 2.70\n(10.37 Schaden pro Sekunde)\nHaltbarkeit 60 / 60\n21" }
entries[3950] = { ["name"] = "Große Bronzebombe", ["text"] = "Wirken in 8 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nSchweres Sprengpulver (2), Bronzebarren (3), Silberkontakt\n(2)\nBenötigt Ingenieurskunst\n(140)\nBenutzen: Fügt 85 bis 115 Feuerschaden zu und betäubt Ziele 2 Sek. lang in einem Umkreis von 5 Metern. Jeglicher Schaden wird den Effekt abbrechen. (1 Min Abklingzeit)" }
entries[3952] = { ["name"] = "Schwacher Rekombobulator", ["text"] = "Wirken in 12.5 sek.\nReagenzien:\nBronzeröhre , Surrendes bronzenes Dingsda (2), Mittleres Leder (2), Moosachat\nSchwacher Rekombobulator\nSchmuck\nBenötigt Ingenieurskunst\n(140)\nBenutzen: Bannt Verwandlungseffekte von einem befreundeten Ziel. Stellt außerdem noch 150 bis 250 Punkt(e) Gesundheit und Mana wieder her. (5 Min Abklingzeit)\n10 Aufladungen" }
entries[3953] = { ["name"] = "Bronzegerüst", ["text"] = "Wirken in 5.125 sek.\nReagenzien:\nBronzebarren (2), Mittleres Leder , Wollstoff" }
entries[3954] = { ["name"] = "Mondsichtgewehr", ["text"] = "Wirken in 25 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nBronzeröhre (3), Surrendes bronzenes Dingsda (3), Schwerer Griff , Geringer Mondstein (2)\nMondsichtgewehr\nWird beim Anlegen gebunden\nDistanz Schusswaffe\n14 - 26 Schaden Tempo 1.70\n(11.76 Schaden pro Sekunde)\nHaltbarkeit 65 / 65\n24" }
entries[3955] = { ["name"] = "Explodierendes Schaf", ["text"] = "Wirken in 8 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nBronzegerüst , Surrendes bronzenes Dingsda , Schweres Sprengpulver (2), Wollstoff (2)\nBenötigt Ingenieurskunst\n(150)\nBenutzen: Beschwört ein explosives Schaf, das den nächstbefindlichen Feind angreift, explodiert und dabei 135 bis 165 Punkt(e) Schaden verursacht. Hält 3 Minuten lang an oder bis zur Explosion. (1 Min Abklingzeit)" }
entries[3956] = { ["name"] = "Schutzbrille mit grünen Gläsern", ["text"] = "Wirken in 12.5 sek.\nTools: Bogenlichtschraubenschlüssel\nReagenzien:\nMittleres Leder (4), Moosachat (2), Fliegerbrille\nSchutzbrille mit grünen Gläsern\nWird beim Anlegen gebunden\nKopf Stoff\n35 Rüstung\n+8 Ausdauer\n+7 Willenskraft\nHaltbarkeit 45 / 45\nBenötigt Ingenieurskunst\n(150)" }
entries[3957] = { ["name"] = "Eisdeflektor", ["text"] = "Wirken in 12.5 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nSurrendes bronzenes Dingsda , Frostöl\n21\nBenutzen: Absorbiert 600 Punkt(e) Frostschaden. Hält 1 Min. lang an. (15 Min Abklingzeit)\n5 Aufladungen" }
entries[3958] = { ["name"] = "Eisenstrebe", ["text"] = "Wirken in 8 sek.\nTools: Schmiedehammer\nReagenzien:\nEisenbarren (2)" }
entries[3959] = { ["name"] = "Diskombobulatorstrahl", ["text"] = "Wirken in 12.5 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nSurrendes bronzenes Dingsda (3), Seidenstoff (2), Jade , Bronzeröhre\nBenutzen: Verwandelt das Ziel in einen Lepragnom und verringert 12 Sek. lang seinen Nahkampf- und Zauberschaden um 40, sowie sein Bewegungstempo um 20%. (1 Min Abklingzeit)\n5 Aufladungen" }
entries[3960] = { ["name"] = "Tragbarer bronzener Mörser", ["text"] = "Wirken in 12.5 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nBronzeröhre (4), Eisenstrebe , Schweres Sprengpulver (4), Mittleres Leder (4)\nBenötigt Ingenieurskunst\n(165)\nBenutzen: Fügt 85 bis 115 Feuerschaden zu und betäubt Ziele 2 Sek. lang in einem Umkreis von 5 Metern. Jeglicher Schaden wird den Effekt abbrechen. (1 Min Abklingzeit)\n8 Aufladungen" }
entries[3961] = { ["name"] = "Gyrochronatom", ["text"] = "Wirken in 8 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nEisenbarren , Goldkraftkern" }
entries[3962] = { ["name"] = "Eisengranate", ["text"] = "Wirken in 8 sek.\nTools: Schmiedehammer\nReagenzien:\nEisenbarren , Schweres Sprengpulver , Seidenstoff\n(2)\nBenötigt Ingenieurskunst\n(175)\nBenutzen: Verursacht 132 bis 218 Feuerschaden und betäubt Ziele 3 Sek. lang innerhalb eines Radius von 3 Metern. Jeglicher Schaden hebt den Effekt auf. (1 Min Abklingzeit)" }
entries[3963] = { ["name"] = "Kompaktes Ernteschnitterset", ["text"] = "Wirken in 25 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nEisenstrebe (2), Bronzegerüst , Gyrochronatom (2), Schweres Leder (4)\n30\nBenötigt Ingenieurskunst\n(175)\nBenutzen: Stellt einen kompakten Ernteschnitter her, der 10 Minuten lang oder bis zu seiner Zerstörung für Euch kämpft. (10 Min Abklingzeit)" }
entries[3965] = { ["name"] = "Hochentwickelte Zielattrappe", ["text"] = "Wirken in 12.5 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nEisenstrebe , Bronzegerüst , Gyrochronatom , Schweres Leder (4)\nBenötigt Ingenieurskunst\n(185)\nBenutzen: Lässt eine Zielattrappe auf den Boden fallen, die in der Nähe befindliche Monster dazu bringt, sie anzugreifen. Die Attrappe bleibt bis zu ihrer Zerstörung aktiv, maximal jedoch für 15 Sekunden. (2 Min Abklingzeit)" }
entries[3966] = { ["name"] = "Handwerkermonokel", ["text"] = "Wirken in 25 sek.\nTools: Bogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nSchweres Leder (6), Citrin (2)\nHandwerkermonokel\nWird beim Anlegen gebunden\nKopf Stoff\n40 Rüstung\n+15 Intelligenz\nHaltbarkeit 45 / 45\n32\nBenötigt Ingenieurskunst\n(185)" }
entries[3967] = { ["name"] = "Große Eisenbombe", ["text"] = "Wirken in 12.5 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nEisenbarren (3), Schweres Sprengpulver (3), Silberkontakt\n(2)\nBenötigt Ingenieurskunst\n(190)\nBenutzen: Fügt 149 bis 201 Feuerschaden zu und betäubt Ziele 3 Sek. lang in einem Umkreis von 5 Metern. Jeglicher Schaden wird den Effekt abbrechen. (1 Min Abklingzeit)\nGeplündert von: Argentumwachposten" }
entries[3968] = { ["name"] = "Goblin-Landmine", ["text"] = "Wirken in 12.5 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nSchweres Sprengpulver (3), Eisenbarren (2), Gyrochronatom\nEine Goblin-Landmine bauen.\nBenötigt Ingenieurskunst\n(195)\nBenutzen: Platziert die Goblin-Landmine auf dem Boden. Sie explodiert, sobald eine feindliche Kreatur an ihr vorbeigeht, und fügt ihr 394 bis 506 Feuerschaden zu. Die Mine ist 1 Min. lang aktiv. (1 Min Abklingzeit)" }
entries[3969] = { ["name"] = "Mechanischer Drachling", ["text"] = "Wirken in 45 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nBronzegerüst , Eisenstrebe (4), Gyrochronatom (4), Citrin (2), Verschmorte Verkabelung\nWird beim Anlegen gebunden\nEinzigartigSchmuck\n30\nBenötigt Ingenieurskunst\n(200)\nBenutzen: Aktiviert Euren mechanischen Drachling, damit er 1 Min. lang für Euch kämpft. Benötigt eine Stunde als Abklingzeit, bevor ein erneuter Einsatz möglich wird. (1 Stunde Abklingzeit)" }
entries[3971] = { ["name"] = "Gnomisches Verbergungsgerät", ["text"] = "Wirken in 45 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nGyrochronatom (4), Jade (2), Geringer Mondstein (2), Citrin (2), Verschmorte Verkabelung\nWird beim Anlegen gebunden\nSchmuck\nBenötigt Ingenieurskunst\n(200)\nBenutzen: Gewährt 10 Sek. lang Unsichtbarkeit. Kann nur alle 60 Minuten gewirkt werden. (1 Stunde Abklingzeit)" }
entries[3972] = { ["name"] = "Große Zephyriumladung", ["text"] = "Wirken in 12.5 sek.\nReagenzien:\nRobustes Sprengpulver (2), Schweres Leder (2), Erfrischendes Quellwasser\nBenötigt Ingenieurskunst\n(200)\nBenutzen: Sprengt schwere verschlossene Türen auf." }
entries[3973] = { ["name"] = "Silberkontakt", ["text"] = "Wirken in 5.125 sek.\nReagenzien:\nSilberbarren\n(5)" }
